export function translateUiText(input: string, language: SiteLanguage): string {
  if (language === 'en' || !input) return input;
  const trimmed = input.trim();
  const mapped = exact[trimmed]?.[language] || v118Translations[trimmed]?.[language];
  if (mapped) return input.replace(trimmed, mapped);
  for (const [rx, fn] of dynamicRules) {
    const match = trimmed.match(rx);
    if (match) return input.replace(trimmed, fn(match, language));
  }
  // Conservative fallback for legacy dynamic labels. Only translate strings that clearly start
  // like UI copy; this avoids changing house names, emails, custom notes and other user data.
  const rules = starterPhrases[language];
  for (const [from,to] of rules) {
    if (trimmed.startsWith(from) && trimmed.length > from.length + 1) {
      return input.replace(trimmed, trimmed.replace(from,to));
    }
  }
  return input;
}

export function languageDisplayName(value: SiteLanguage, current: SiteLanguage): string {
  const names: Record<SiteLanguage, string> = {
    en: 'English',
    gu: 'ગુજરાતી',
    hi: 'हिंदी',
    fr: 'Français',
  };
  return names[value];
}
